-- v36.5.5 — Ελεγχόμενη εισαγωγή καταλόγου Υπηρεσιών στο STAGING.
-- Πηγή: αναγνωστική εξαγωγή της προηγούμενης εφαρμογής (2026-08-05T14:58:09.295849+00:00).
-- Το SQL προορίζεται αποκλειστικά για το promitheies-rodou-staging.
-- Δεν εισάγει το legacy tender override SRV01, επειδή περιέγραφε προμήθεια νέων
-- κλιματιστικών και όχι υπηρεσία συντήρησης.

begin;

create table if not exists public.app_catalog_migrations (
  id text primary key,
  source_format text not null,
  source_generated_at timestamptz,
  group_count integer not null,
  item_count integer not null,
  metadata jsonb not null default '{}'::jsonb,
  applied_at timestamptz not null default now()
);

alter table public.app_catalog_migrations enable row level security;
revoke all on public.app_catalog_migrations from public, anon, authenticated;

do $$
declare
  v_version text;
begin
  select public.app_schema_version() into v_version;
  if v_version not in ('36.5.1', '36.5.5') then
    raise exception 'Απαιτείται schema 36.5.1 πριν από την εισαγωγή υπηρεσιών. Βρέθηκε: %', v_version;
  end if;

  if exists (select 1 from public.app_catalog_migrations where id = '202608050007_service_catalog') then
    return;
  end if;

  if (select count(*) from public.municipal_units where is_active) <> 11 then
    raise exception 'Ο έλεγχος ασφαλείας απέτυχε: αναμένονται 11 ενεργές μονάδες στο κενό staging.';
  end if;
  if (select count(*) from public.procurement_groups where domain = 'procurement' and is_active) <> 14 then
    raise exception 'Ο έλεγχος ασφαλείας απέτυχε: αναμένονται 14 ενεργές ομάδες προμηθειών.';
  end if;
  if (
    select count(*)
    from public.materials m
    join public.procurement_groups g on g.id = m.group_id
    where g.domain = 'procurement' and m.is_active
  ) <> 918 then
    raise exception 'Ο έλεγχος ασφαλείας απέτυχε: αναμένονται 918 ενεργά είδη προμηθειών.';
  end if;
  if exists (select 1 from public.procurement_groups where domain = 'service') then
    raise exception 'Υπάρχουν ήδη ομάδες υπηρεσιών χωρίς καταγεγραμμένη migration. Η εισαγωγή ακυρώθηκε χωρίς αλλαγές.';
  end if;
  if exists (select 1 from public.materials where code = any(array['SRV01-01', 'SRV01-02', 'SRV01-03', 'SRV01-04', 'SRV01-05', 'SRV01-06', 'SRV01-07', 'SRV01-08', 'SRV01-09', 'SRV01-10', 'SRV01-11', 'SRV01-12', 'SRV01-13', 'SRV01-14', 'SRV01-15', 'SRV01-16', 'SRV01-17', 'SRV01-18', 'SRV01-19', 'SRV01-20', 'SRV01-21', 'SRV01-22', 'SRV01-23', 'SRV01-24', 'SRV01-25', 'SRV02-01', 'SRV02-02', 'SRV02-03', 'SRV02-04', 'SRV02-05', 'SRV02-06', 'SRV02-07', 'SRV02-08', 'SRV02-09', 'SRV02-10', 'SRV02-11', 'SRV02-12', 'SRV02-13', 'SRV02-14', 'SRV02-15', 'SRV02-16', 'SRV02-17', 'SRV02-18', 'SRV02-19', 'SRV02-20', 'SRV03-01', 'SRV03-02', 'SRV03-03', 'SRV03-04', 'SRV03-05', 'SRV03-06', 'SRV03-07', 'SRV03-08', 'SRV03-09', 'SRV03-10', 'SRV03-11', 'SRV03-12', 'SRV03-13', 'SRV03-14', 'SRV03-15', 'SRV03-16', 'SRV03-17', 'SRV03-18', 'SRV03-19', 'SRV03-20', 'SRV03-21', 'SRV03-22', 'SRV04-01', 'SRV04-02', 'SRV04-03', 'SRV04-04', 'SRV04-05', 'SRV04-06', 'SRV04-07', 'SRV04-08', 'SRV04-09', 'SRV04-10', 'SRV04-11', 'SRV04-12', 'SRV04-13', 'SRV04-14', 'SRV04-15', 'SRV04-16', 'SRV04-17', 'SRV04-18', 'SRV04-19', 'SRV04-20', 'SRV04-21', 'SRV04-22', 'SRV04-23', 'SRV05-01', 'SRV05-02', 'SRV05-03', 'SRV05-04', 'SRV05-05', 'SRV05-06', 'SRV05-07', 'SRV05-08', 'SRV05-09', 'SRV05-10', 'SRV05-11', 'SRV05-12', 'SRV05-13', 'SRV05-14', 'SRV05-15', 'SRV05-16', 'SRV05-17', 'SRV05-18', 'SRV05-19', 'SRV05-20', 'SRV05-21', 'SRV05-22', 'SRV06-01', 'SRV06-02', 'SRV06-03', 'SRV06-04', 'SRV06-05', 'SRV06-06', 'SRV06-07', 'SRV06-08', 'SRV06-09', 'SRV06-10', 'SRV06-11', 'SRV06-12', 'SRV06-13', 'SRV06-14', 'SRV06-15', 'SRV06-16', 'SRV06-17', 'SRV06-18', 'SRV06-19', 'SRV06-20', 'SRV06-21', 'SRV06-22', 'SRV07-01', 'SRV07-02', 'SRV07-03', 'SRV07-04', 'SRV07-05', 'SRV07-06', 'SRV07-07', 'SRV07-08', 'SRV07-09', 'SRV07-10', 'SRV07-11', 'SRV07-12', 'SRV07-13', 'SRV07-14', 'SRV07-15', 'SRV07-16', 'SRV07-17', 'SRV07-18', 'SRV07-19', 'SRV07-20', 'SRV07-21', 'SRV07-22', 'SRV08-01', 'SRV08-02', 'SRV08-03', 'SRV08-04', 'SRV08-05', 'SRV08-06', 'SRV08-07', 'SRV08-08', 'SRV08-09', 'SRV08-10', 'SRV08-11', 'SRV08-12', 'SRV08-13', 'SRV08-14', 'SRV08-15', 'SRV08-16', 'SRV08-17', 'SRV08-18', 'SRV08-19', 'SRV08-20', 'SRV08-21', 'SRV08-22'])) then
    raise exception 'Υπάρχει ήδη κωδικός εργασίας SRV/legacy στο staging. Η εισαγωγή ακυρώθηκε χωρίς αλλαγές.';
  end if;
end
$$;

insert into public.procurement_groups (code, name, short_name, sort_order, domain, is_active)
select * from (values
