with service_items(group_code, code, name, short_name, subcategory, unit, cpv, technical_specs, standards, ce_required, notes_for_tender, default_unit_price, is_active, sort_order) as (
  values
  ('SRV01', 'SRV01-01', 'Συντήρηση/καθαρισμός split τοίχου έως 12.000 BTU', 'Συντήρηση/καθαρισμός split τοίχου έως 12.000 BTU', 'Προληπτική συντήρηση & έλεγχοι', 'τεμ.', '50730000-1', 'Πλήρης προληπτική συντήρηση εσωτερικής και εξωτερικής μονάδας: καθαρισμός φίλτρων και εναλλακτών, καθαρισμός λεκάνης και δικτύου αποχέτευσης συμπυκνωμάτων, έλεγχος πιέσεων, θερμοκρασιών και ηλεκτρικών μεγεθών, οπτικός έλεγχος διαρροών, σύσφιξη ακροδεκτών. Εκτελείται από αδειούχο τεχνικό ψυκτικό (Π.Δ. 1/2013), σύμφωνα με το ΕΝ 378 και τις οδηγίες του κατασκευαστή. Παραδοτέο: φύλλο συντήρησης.', 'Π.Δ. 1/2013 · Κανονισμός (ΕΕ) 2024/573 · Εκτελεστικός Κανονισμός (ΕΕ) 2024/2215 · ΕΛΟΤ EN 378 (ή ισοδύναμο) · οδηγίες κατασκευαστή', false, null, 25, true, 1),
  ('SRV01', 'SRV01-02', 'Συντήρηση/καθαρισμός split τοίχου 12.001–24.000 BTU', 'Συντήρηση/καθαρισμός split τοίχου 12.001–24.000 BTU', 'Προληπτική συντήρηση & έλεγχοι', 'τεμ.', '50730000-1', 'Όπως η συντήρηση μικρής μονάδας, για κλιματιστικό μεγαλύτερης ισχύος: πλήρης καθαρισμός φίλτρων, εναλλακτών και αποχέτευσης, έλεγχος λειτουργικών και ηλεκτρικών μεγεθών, έλεγχος διαρροών. Από αδειούχο ψυκτικό (Π.Δ. 1/2013), κατά ΕΝ 378 και οδηγίες κατασκευαστή. Παραδοτέο: φύλλο συντήρησης.', 'Π.Δ. 1/2013 · Κανονισμός (ΕΕ) 2024/573 · Εκτελεστικός Κανονισμός (ΕΕ) 2024/2215 · ΕΛΟΤ EN 378 (ή ισοδύναμο) · οδηγίες κατασκευαστή', false, null, 30, true, 2),
  ('SRV01', 'SRV01-03', 'Συντήρηση κλιματιστικού άνω των 24.000 BTU (ντουλάπα/οροφής/ημικεντρικό)', 'Συντήρηση κλιματιστικού άνω των 24.000 BTU (ντουλάπα/οροφής/ημικεντρικό)', 'Προληπτική συντήρηση & έλεγχοι', 'τεμ.', '50730000-1', 'Συντήρηση μονάδας μεγάλης ισχύος (ντουλάπα, οροφής, ημικεντρικό): καθαρισμός ή χημικός καθαρισμός στοιχείων, καθαρισμός φίλτρων και αποχέτευσης, έλεγχος ανεμιστήρων και ιμάντων, έλεγχος αυτοματισμών και διατάξεων προστασίας, μετρήσεις λειτουργίας. Από αδειούχο ψυκτικό, κατά ΕΝ 378. Παραδοτέο: φύλλο συντήρησης.', 'Π.Δ. 1/2013 · Κανονισμός (ΕΕ) 2024/573 · Εκτελεστικός Κανονισμός (ΕΕ) 2024/2215 · ΕΛΟΤ EN 378 (ή ισοδύναμο) · οδηγίες κατασκευαστή', false, null, 55, true, 3),
  ('SRV01', 'SRV01-04', 'Συντήρηση εσωτερικής μονάδας VRV/VRF', 'Συντήρηση εσωτερικής μονάδας VRV/VRF', 'Προληπτική συντήρηση & έλεγχοι', 'τεμ.', '50730000-1', 'Συντήρηση εσωτερικής μονάδας συστήματος VRV/VRF: καθαρισμός φίλτρων, στοιχείου και δικτύου συμπυκνωμάτων, έλεγχος εκτονωτικής βαλβίδας, ελέγχου επικοινωνίας και διευθυνσιοδότησης, έλεγχος παραμέτρων κατά τον κατασκευαστή. Από αδειούχο ψυκτικό με εμπειρία σε συστήματα VRV/VRF.', 'Π.Δ. 1/2013 · Κανονισμός (ΕΕ) 2024/573 · Εκτελεστικός Κανονισμός (ΕΕ) 2024/2215 · ΕΛΟΤ EN 378 (ή ισοδύναμο) · οδηγίες κατασκευαστή', false, null, 45, true, 4),
  ('SRV01', 'SRV01-05', 'Βιολογικός/βαθύς καθαρισμός με αποστείρωση', 'Βιολογικός/βαθύς καθαρισμός με αποστείρωση', 'Προληπτική συντήρηση & έλεγχοι', 'τεμ.', '50730000-1', 'Βιολογικός καθαρισμός: χημικός καθαρισμός στοιχείων και φτερωτής με εγκεκριμένα καθαριστικά και εφαρμογή αντιμικροβιακού απολυμαντικού, κατάλληλου για χώρους όπου παρευρίσκεται κοινό, με προστασία των ηλεκτρικών μερών και έκπλυση. Παραδίδεται σε πλήρη λειτουργία.', 'Π.Δ. 1/2013 · Κανονισμός (ΕΕ) 2024/573 · Εκτελεστικός Κανονισμός (ΕΕ) 2024/2215 · ΕΛΟΤ EN 378 (ή ισοδύναμο) · οδηγίες κατασκευαστή', false, null, 45, true, 5),
  ('SRV01', 'SRV01-06', 'Πλήρωση/συμπλήρωση ψυκτικού μέσου R32/R410A', 'Πλήρωση/συμπλήρωση ψυκτικού μέσου R32/R410A', 'Προληπτική συντήρηση & έλεγχοι', 'kg', '50730000-1', 'Συμπλήρωση ή πλήρωση ψυκτικού μέσου R32/R410A κατόπιν ελέγχου στεγανότητας. Ζύγιση της προστιθέμενης ποσότητας και καταγραφή στο φύλλο εργασιών, σύμφωνα με τις υποχρεώσεις του Κανονισμού (ΕΕ) 2024/573. Από πιστοποιημένο χειριστή φθοριούχων αερίων κατά τον Εκτελεστικό Κανονισμό (ΕΕ) 2024/2215. Τιμή ανά κιλό.', 'Π.Δ. 1/2013 · Κανονισμός (ΕΕ) 2024/573 · Εκτελεστικός Κανονισμός (ΕΕ) 2024/2215 · ΕΛΟΤ EN 378 (ή ισοδύναμο) · οδηγίες κατασκευαστή', false, null, 35, true, 6),
  ('SRV01', 'SRV01-07', 'Καθαρισμός/απολύμανση αεραγωγών', 'Καθαρισμός/απολύμανση αεραγωγών', 'Προληπτική συντήρηση & έλεγχοι', 'μ.μ.', '50730000-1', 'Μηχανικός καθαρισμός αεραγωγών με βούρτσισμα και ταυτόχρονη αναρρόφηση, και απολύμανση των εσωτερικών επιφανειών με εγκεκριμένα σκευάσματα, λαμβανομένου υπόψη του ΕΝ 15780. Τιμή ανά τρέχον μέτρο δικτύου.', 'Π.Δ. 1/2013 · Κανονισμός (ΕΕ) 2024/573 · Εκτελεστικός Κανονισμός (ΕΕ) 2024/2215 · ΕΛΟΤ EN 378 (ή ισοδύναμο) · οδηγίες κατασκευαστή · ΕΛΟΤ EN 15780', false, null, 8, true, 7),
  ('SRV01', 'SRV01-08', 'Έκτακτη επίσκεψη/διάγνωση βλάβης (τεχνικός ψυκτικός)', 'Έκτακτη επίσκεψη/διάγνωση βλάβης (τεχνικός ψυκτικός)', 'Προληπτική συντήρηση & έλεγχοι', 'ώρα', '50730000-1', 'Έκτακτη επίσκεψη για διάγνωση βλάβης: προσέλευση εντός 48 ωρών από την ειδοποίηση, διάγνωση με κατάλληλα όργανα, σύνταξη σύντομης τεχνικής έκθεσης βλάβης και εκτίμησης αποκατάστασης. Τιμή ανά ώρα απασχόλησης αδειούχου ψυκτικού.', 'Π.Δ. 1/2013 · Κανονισμός (ΕΕ) 2024/573 · Εκτελεστικός Κανονισμός (ΕΕ) 2024/2215 · ΕΛΟΤ EN 378 (ή ισοδύναμο) · οδηγίες κατασκευαστή', false, null, 35, true, 8),
  ('SRV01', 'SRV01-09', 'Έλεγχος καλής λειτουργίας & έκδοση φύλλου συντήρησης', 'Έλεγχος καλής λειτουργίας & έκδοση φύλλου συντήρησης', 'Προληπτική συντήρηση & έλεγχοι', 'τεμ.', '50730000-1', 'Έλεγχος καλής λειτουργίας: μέτρηση διαφοράς θερμοκρασίας αέρα, πιέσεων λειτουργίας, ρευμάτων, έλεγχος διατάξεων ασφαλείας και αποχέτευσης. Έκδοση φύλλου ελέγχου με ευρήματα και συστάσεις.', 'Π.Δ. 1/2013 · Κανονισμός (ΕΕ) 2024/573 · Εκτελεστικός Κανονισμός (ΕΕ) 2024/2215 · ΕΛΟΤ EN 378 (ή ισοδύναμο) · οδηγίες κατασκευαστή', false, null, 15, true, 9),
  ('SRV01', 'SRV01-10', 'Επισκευή πλακέτας ελέγχου (inverter)', 'Επισκευή πλακέτας ελέγχου (inverter)', 'Επισκευές ψυκτικού κυκλώματος & αυτοματισμών', 'τεμ.', '50730000-1', 'Διάγνωση και επισκευή ηλεκτρονικής πλακέτας ελέγχου (inverter) σε επίπεδο εξαρτήματος (πυκνωτές, ρελέ, βαρίστορ, ψυκτικά στοιχεία), με έλεγχο τροφοδοσίας και επικοινωνίας και δοκιμές σε ψύξη και θέρμανση. Εγγύηση εργασίας τουλάχιστον έξι μηνών. Από αδειούχο τεχνικό ψυκτικό (Π.Δ. 1/2013).', 'Π.Δ. 1/2013 · Κανονισμός (ΕΕ) 2024/573 · Εκτελεστικός Κανονισμός (ΕΕ) 2024/2215 · ΕΛΟΤ EN 378 (ή ισοδύναμο) · οδηγίες κατασκευαστή', false, null, 100, true, 10),
  ('SRV01', 'SRV01-11', 'Αντικατάσταση συμπιεστή split (έως 24.000 BTU)', 'Αντικατάσταση συμπιεστή split (έως 24.000 BTU)', 'Επισκευές ψυκτικού κυκλώματος & αυτοματισμών', 'τεμ.', '50730000-1', 'Αντικατάσταση συμπιεστή: ανάκτηση ψυκτικού μέσου με πιστοποιημένο εξοπλισμό (Κανονισμός (ΕΕ) 2024/573), αντικατάσταση συμπιεστή και φίλτρου γραμμής, συγκολλήσεις, δημιουργία κενού, πλήρωση και δοκιμές κατά ΕΝ 378. Από αδειούχο ψυκτικό.', 'Π.Δ. 1/2013 · Κανονισμός (ΕΕ) 2024/573 · Εκτελεστικός Κανονισμός (ΕΕ) 2024/2215 · ΕΛΟΤ EN 378 (ή ισοδύναμο) · οδηγίες κατασκευαστή', false, null, 180, true, 11),
  ('SRV01', 'SRV01-12', 'Αντικατάσταση τετράοδης βαλβίδας', 'Αντικατάσταση τετράοδης βαλβίδας', 'Επισκευές ψυκτικού κυκλώματος & αυτοματισμών', 'τεμ.', '50730000-1', 'Αντικατάσταση τετράοδης βαλβίδας: ανάκτηση ψυκτικού, αντικατάσταση βαλβίδας με συγκόλληση, δημιουργία κενού, πλήρωση και δοκιμή εναλλαγής λειτουργίας ψύξης/θέρμανσης.', 'Π.Δ. 1/2013 · Κανονισμός (ΕΕ) 2024/573 · Εκτελεστικός Κανονισμός (ΕΕ) 2024/2215 · ΕΛΟΤ EN 378 (ή ισοδύναμο) · οδηγίες κατασκευαστή', false, null, 70, true, 12),
  ('SRV01', 'SRV01-13', 'Αντικατάσταση φτερωτής/μοτέρ ανεμιστήρα', 'Αντικατάσταση φτερωτής/μοτέρ ανεμιστήρα', 'Επισκευές ψυκτικού κυκλώματος & αυτοματισμών', 'τεμ.', '50730000-1', 'Αντικατάσταση φτερωτής ή κινητήρα ανεμιστήρα με γνήσιο ή συμβατό ανταλλακτικό, έλεγχος ζυγοστάθμισης, θορύβου και κραδασμών, δοκιμή λειτουργίας.', 'Π.Δ. 1/2013 · Κανονισμός (ΕΕ) 2024/573 · Εκτελεστικός Κανονισμός (ΕΕ) 2024/2215 · ΕΛΟΤ EN 378 (ή ισοδύναμο) · οδηγίες κατασκευαστή', false, null, 60, true, 13),
  ('SRV01', 'SRV01-14', 'Ανίχνευση & αποκατάσταση διαρροής ψυκτικού', 'Ανίχνευση & αποκατάσταση διαρροής ψυκτικού', 'Επισκευές ψυκτικού κυκλώματος & αυτοματισμών', 'τεμ.', '50730000-1', 'Ανίχνευση διαρροής ψυκτικού με ηλεκτρονικό ανιχνευτή, μέθοδο UV ή αφρίζον υγρό, αποκατάσταση με συγκόλληση ή αντικατάσταση ρακόρ και δοκιμή πίεσης με άζωτο πριν την επαναπλήρωση.', 'Π.Δ. 1/2013 · Κανονισμός (ΕΕ) 2024/573 · Εκτελεστικός Κανονισμός (ΕΕ) 2024/2215 · ΕΛΟΤ EN 378 (ή ισοδύναμο) · οδηγίες κατασκευαστή', false, null, 55, true, 14),
  ('SRV01', 'SRV01-15', 'Εκκένωση & δημιουργία κενού (vacuum) εγκατάστασης', 'Εκκένωση & δημιουργία κενού (vacuum) εγκατάστασης', 'Επισκευές ψυκτικού κυκλώματος & αυτοματισμών', 'τεμ.', '50730000-1', 'Εκκένωση και δημιουργία κενού στην εγκατάσταση με αντλία κενού, επίτευξη και διατήρηση του κενού σύμφωνα με τις απαιτήσεις του κατασκευαστή, με έλεγχο ανόδου πίεσης, πριν από κάθε πλήρωση.', 'Π.Δ. 1/2013 · Κανονισμός (ΕΕ) 2024/573 · Εκτελεστικός Κανονισμός (ΕΕ) 2024/2215 · ΕΛΟΤ EN 378 (ή ισοδύναμο) · οδηγίες κατασκευαστή', false, null, 40, true, 15),
  ('SRV01', 'SRV01-16', 'Αποξήλωση κλιματιστικού split', 'Αποξήλωση κλιματιστικού split', 'Αποξήλωση, μεταφορά & εγκατάσταση', 'τεμ.', '50730000-1', 'Πλήρης αποξήλωση κλιματιστικού (εσωτερικής και εξωτερικής μονάδας) με προηγούμενη ανάκτηση του ψυκτικού μέσου από πιστοποιημένο τεχνικό, αποσύνδεση δικτύων, τάπωμα σωληνώσεων, αποκατάσταση οπών και επιφανειών και καθαρισμό του χώρου. Μεταφορά και παράδοση των μονάδων σε χώρο που θα υποδείξει ο Δήμος ή σε εγκεκριμένο σύστημα εναλλακτικής διαχείρισης ΑΗΗΕ.', 'Π.Δ. 1/2013 · Κανονισμός (ΕΕ) 2024/573 · Εκτελεστικός Κανονισμός (ΕΕ) 2024/2215 · ΕΛΟΤ EN 378 (ή ισοδύναμο) · οδηγίες κατασκευαστή · Οδηγία 2012/19/ΕΕ και ισχύον ελληνικό πλαίσιο ΑΗΗΕ', false, null, 35, true, 16),
  ('SRV01', 'SRV01-17', 'Μεταφορά & επανεγκατάσταση split (έως 24.000 BTU)', 'Μεταφορά & επανεγκατάσταση split (έως 24.000 BTU)', 'Αποξήλωση, μεταφορά & εγκατάσταση', 'τεμ.', '50730000-1', 'Μεταφορά και επανεγκατάσταση κλιματιστικού: αποξήλωση με ανάκτηση ψυκτικού, μεταφορά, νέες βάσεις και στηρίγματα, επανασύνδεση με υφιστάμενη ή νέα ψυκτική γραμμή έως 3 μέτρα, δημιουργία κενού, συμπλήρωση ψυκτικού εφόσον απαιτηθεί, θέση σε λειτουργία και δοκιμές.', 'Π.Δ. 1/2013 · Κανονισμός (ΕΕ) 2024/573 · Εκτελεστικός Κανονισμός (ΕΕ) 2024/2215 · ΕΛΟΤ EN 378 (ή ισοδύναμο) · οδηγίες κατασκευαστή', false, null, 90, true, 17),
  ('SRV01', 'SRV01-18', 'Νέα εγκατάσταση split (έως 24.000 BTU, έως 3μ γραμμή)', 'Νέα εγκατάσταση split (έως 24.000 BTU, έως 3μ γραμμή)', 'Αποξήλωση, μεταφορά & εγκατάσταση', 'τεμ.', '50730000-1', 'Νέα εγκατάσταση κλιματιστικού: βάσεις στήριξης, διατρήσεις, ψυκτική γραμμή έως 3 μέτρα με μόνωση, ηλεκτρική διασύνδεση, κανάλι όδευσης, αποχέτευση συμπυκνωμάτων, δημιουργία κενού και θέση σε λειτουργία με δοκιμές. Υλικά με σήμανση CE. Από αδειούχο ψυκτικό.', 'Π.Δ. 1/2013 · Κανονισμός (ΕΕ) 2024/573 · Εκτελεστικός Κανονισμός (ΕΕ) 2024/2215 · ΕΛΟΤ EN 378 (ή ισοδύναμο) · οδηγίες κατασκευαστή', false, null, 120, true, 18),
  ('SRV01', 'SRV01-19', 'Επιμήκυνση χαλκοσωλήνων ψυκτικού', 'Επιμήκυνση χαλκοσωλήνων ψυκτικού', 'Αποξήλωση, μεταφορά & εγκατάσταση', 'μ.μ.', '50730000-1', 'Επιμήκυνση ψυκτικής γραμμής: ζεύγος χαλκοσωλήνων ψυκτικής ποιότητας κατά ΕΝ 12735-1 με μόνωση, καλώδιο διασύνδεσης, σωλήνας αποχέτευσης και κανάλι όδευσης, πλήρως τοποθετημένα. Τιμή ανά τρέχον μέτρο.', 'Π.Δ. 1/2013 · Κανονισμός (ΕΕ) 2024/573 · Εκτελεστικός Κανονισμός (ΕΕ) 2024/2215 · ΕΛΟΤ EN 378 (ή ισοδύναμο) · οδηγίες κατασκευαστή · ΕΛΟΤ EN 12735-1', false, null, 12, true, 19),
  ('SRV01', 'SRV01-20', 'Αντικατάσταση τηλεχειριστηρίου', 'Αντικατάσταση τηλεχειριστηρίου', 'Ανταλλακτικά & ειδικές επισκευές', 'τεμ.', '50730000-1', 'Προμήθεια και παραμετροποίηση πλήρως συμβατού τηλεχειριστηρίου (γνήσιου ή κατάλληλου πολυχειριστηρίου) με δοκιμή όλων των λειτουργιών.', 'Π.Δ. 1/2013 · Κανονισμός (ΕΕ) 2024/573 · Εκτελεστικός Κανονισμός (ΕΕ) 2024/2215 · ΕΛΟΤ EN 378 (ή ισοδύναμο) · οδηγίες κατασκευαστή', false, null, 25, true, 20),
  ('SRV01', 'SRV01-21', 'Αντικατάσταση φίλτρου ενεργού άνθρακα', 'Αντικατάσταση φίλτρου ενεργού άνθρακα', 'Ανταλλακτικά & ειδικές επισκευές', 'τεμ.', '50730000-1', 'Προμήθεια και τοποθέτηση φίλτρου ενεργού άνθρακα, γνήσιου ή συμβατού με τη μονάδα, με έλεγχο εφαρμογής.', 'Π.Δ. 1/2013 · Κανονισμός (ΕΕ) 2024/573 · Εκτελεστικός Κανονισμός (ΕΕ) 2024/2215 · ΕΛΟΤ EN 378 (ή ισοδύναμο) · οδηγίες κατασκευαστή', false, null, 12, true, 21),
  ('SRV01', 'SRV01-22', 'Συντήρηση ανεμιστήρα/αφυγραντήρα', 'Συντήρηση ανεμιστήρα/αφυγραντήρα', 'Ανταλλακτικά & ειδικές επισκευές', 'τεμ.', '50730000-1', 'Συντήρηση ανεμιστήρα ή αφυγραντήρα: καθαρισμός φίλτρων και πτερωτής, λίπανση εδράνων, έλεγχος ηλεκτρικών μερών και δοκιμή λειτουργίας.', 'Π.Δ. 1/2013 · Κανονισμός (ΕΕ) 2024/573 · Εκτελεστικός Κανονισμός (ΕΕ) 2024/2215 · ΕΛΟΤ EN 378 (ή ισοδύναμο) · οδηγίες κατασκευαστή', false, null, 20, true, 22),
  ('SRV01', 'SRV01-23', 'Αντικατάσταση πλακέτας κλιματιστικού έως 12.000 BTU', 'Αντικατάσταση πλακέτας κλιματιστικού έως 12.000 BTU', 'Ανταλλακτικά & ειδικές επισκευές', 'τεμ.', '50730000-1', 'Αντικατάσταση ηλεκτρονικής πλακέτας ελέγχου (inverter) σε κλιματιστικό έως 12.000 BTU με γνήσια ή πλήρως συμβατή, επαναπρογραμματισμός και παραμετροποίηση όπου απαιτείται, δοκιμές σε ψύξη και θέρμανση. Στην τιμή περιλαμβάνονται το ανταλλακτικό και η εργασία. Εγγύηση τουλάχιστον έξι μηνών. Από αδειούχο τεχνικό ψυκτικό (Π.Δ. 1/2013).', 'Π.Δ. 1/2013 · Κανονισμός (ΕΕ) 2024/573 · Εκτελεστικός Κανονισμός (ΕΕ) 2024/2215 · ΕΛΟΤ EN 378 (ή ισοδύναμο) · οδηγίες κατασκευαστή', false, null, 300, true, 23),
  ('SRV01', 'SRV01-24', 'Αντικατάσταση πλακέτας κλιματιστικού άνω των 12.000 BTU', 'Αντικατάσταση πλακέτας κλιματιστικού άνω των 12.000 BTU', 'Ανταλλακτικά & ειδικές επισκευές', 'τεμ.', '50730000-1', 'Αντικατάσταση ηλεκτρονικής πλακέτας ελέγχου (inverter) σε κλιματιστικό άνω των 12.000 BTU (μεγάλα split, ντουλάπες, οροφής, ημικεντρικά) με γνήσια ή πλήρως συμβατή, επαναπρογραμματισμός και παραμετροποίηση όπου απαιτείται, δοκιμές σε ψύξη και θέρμανση. Στην τιμή περιλαμβάνονται το ανταλλακτικό και η εργασία. Εγγύηση τουλάχιστον έξι μηνών. Από αδειούχο τεχνικό ψυκτικό (Π.Δ. 1/2013).', 'Π.Δ. 1/2013 · Κανονισμός (ΕΕ) 2024/573 · Εκτελεστικός Κανονισμός (ΕΕ) 2024/2215 · ΕΛΟΤ EN 378 (ή ισοδύναμο) · οδηγίες κατασκευαστή', false, null, 500, true, 24),
  ('SRV01', 'SRV01-25', 'Αντικατάσταση πλακέτας κλιματιστικού άνω των 40.000 BTU', 'Αντικατάσταση πλακέτας κλιματιστικού άνω των 40.000 BTU', 'Ανταλλακτικά & ειδικές επισκευές', 'τεμ.', '50730000-1', 'Αντικατάσταση ηλεκτρονικής πλακέτας ελέγχου (inverter) σε κλιματιστικό άνω των 12.000 BTU (μεγάλα split, ντουλάπες, οροφής, ημικεντρικά) με γνήσια ή πλήρως συμβατή, επαναπρογραμματισμός και παραμετροποίηση όπου απαιτείται, δοκιμές σε ψύξη και θέρμανση. Στην τιμή περιλαμβάνονται το ανταλλακτικό και η εργασία. Εγγύηση τουλάχιστον έξι μηνών. Από αδειούχο τεχνικό ψυκτικό (Π.Δ. 1/2013).', 'Π.Δ. 1/2013 · Κανονισμός (ΕΕ) 2024/573 · Εκτελεστικός Κανονισμός (ΕΕ) 2024/2215 · ΕΛΟΤ EN 378 (ή ισοδύναμο) · οδηγίες κατασκευαστή', false, null, 2580, true, 25),
  ('SRV02', 'SRV02-01', 'Έκδοση ΥΔΕ μονοφασικής παροχής (κατοικία/μικρό κτίριο)', 'Έκδοση ΥΔΕ μονοφασικής παροχής (κατοικία/μικρό κτίριο)', 'ΥΔΕ & πιστοποιήσεις', 'τεμ.', '71314100-3', 'Πλήρης έλεγχος μονοφασικής ηλεκτρικής εγκατάστασης (οπτικός έλεγχος, δοκιμές και μετρήσεις: συνέχεια αγωγών προστασίας, αντίσταση μόνωσης, βρόχος σφάλματος, λειτουργία διατάξεων διαφορικού ρεύματος, αντίσταση γείωσης) και σύνταξη Υπεύθυνης Δήλωσης Εγκαταστάτη (ΥΔΕ) με τα συνημμένα (πρωτόκολλο ελέγχου, μονογραμμικά σχέδια, κάτοψη) σύμφωνα με την ΥΑ 101195/2021 (ΦΕΚ 4654/Β) και το ισχύον κατά περίπτωση πρότυπο (ΕΛΟΤ 60364 / ΕΛΟΤ HD 384 / ΚΕΗΕ). Από αδειούχο ηλεκτρολόγο εγκαταστάτη. Παράδοση πλήρους φακέλου.', 'Υ.Α. 101195/17.09.2021 (Β΄ 4654), όπως τροποποιήθηκε και ισχύει · ΕΛΟΤ 60364 ή, κατά περίπτωση, ΕΛΟΤ HD 384/ΚΕΗΕ · σειρά ΕΛΟΤ EN 61557', false, null, 90, true, 1),
  ('SRV02', 'SRV02-02', 'Έκδοση ΥΔΕ τριφασικής παροχής', 'Έκδοση ΥΔΕ τριφασικής παροχής', 'ΥΔΕ & πιστοποιήσεις', 'τεμ.', '71314100-3', 'Όπως ο έλεγχος μονοφασικής εγκατάστασης, για τριφασική παροχή, με μετρήσεις και στις τρεις φάσεις και έλεγχο συμμετρίας φορτίων. Σύνταξη πλήρους φακέλου ΥΔΕ κατά την ΥΑ 101195/2021 από αδειούχο ηλεκτρολόγο εγκαταστάτη κατάλληλης κατηγορίας.', 'Υ.Α. 101195/17.09.2021 (Β΄ 4654), όπως τροποποιήθηκε και ισχύει · ΕΛΟΤ 60364 ή, κατά περίπτωση, ΕΛΟΤ HD 384/ΚΕΗΕ · σειρά ΕΛΟΤ EN 61557', false, null, 150, true, 2),
  ('SRV02', 'SRV02-03', 'Επανέλεγχος ηλεκτρικής εγκατάστασης κατά ΕΛΟΤ 60364 ή το εφαρμοστέο παλαιότερο πλαίσιο', 'Επανέλεγχος ηλεκτρικής εγκατάστασης κατά ΕΛΟΤ 60364 ή το εφαρμοστέο παλαιότερο πλαίσιο', 'ΥΔΕ & πιστοποιήσεις', 'τεμ.', '71314100-3', 'Επανέλεγχος υφιστάμενης εγκατάστασης με οπτική επιθεώρηση, δοκιμές και μετρήσεις κατά ΕΛΟΤ 60364 ή, για εγκατάσταση που έχει κατασκευαστεί με παλαιότερο κανονιστικό πλαίσιο, κατά ΕΛΟΤ HD 384/ΚΕΗΕ όπως επιτρέπει η Υ.Α. 101195/2021, όπως ισχύει. Χρησιμοποιούνται κατάλληλα και διακριβωμένα όργανα και παραδίδονται τα προβλεπόμενα πρωτόκολλα ελέγχου και πλήρης ΥΔΕ.', 'Υ.Α. 101195/17.09.2021 (Β΄ 4654), όπως τροποποιήθηκε και ισχύει · ΕΛΟΤ 60364 ή, κατά περίπτωση, ΕΛΟΤ HD 384/ΚΕΗΕ · σειρά ΕΛΟΤ EN 61557', false, null, 120, true, 3),
  ('SRV02', 'SRV02-04', 'Έκδοση ΥΔΕ κοινοχρήστων/δημοτικού κτιρίου', 'Έκδοση ΥΔΕ κοινοχρήστων/δημοτικού κτιρίου', 'ΥΔΕ & πιστοποιήσεις', 'τεμ.', '71314100-3', 'Έλεγχος και έκδοση ΥΔΕ εγκατάστασης κοινοχρήστων ή δημοτικού κτιρίου, με αποτύπωση πινάκων και κυκλωμάτων, πλήρεις μετρήσεις και φάκελο κατά την ΥΑ 101195/2021.', 'Υ.Α. 101195/17.09.2021 (Β΄ 4654), όπως τροποποιήθηκε και ισχύει · ΕΛΟΤ 60364 ή, κατά περίπτωση, ΕΛΟΤ HD 384/ΚΕΗΕ · σειρά ΕΛΟΤ EN 61557', false, null, 180, true, 4),
  ('SRV02', 'SRV02-05', 'Άρση επικινδυνότητας/μικροεπισκευές αποκατάστασης', 'Άρση επικινδυνότητας/μικροεπισκευές αποκατάστασης', 'Αποκαταστάσεις & ηλεκτρολογικές εργασίες', 'ώρα', '71314100-3', 'Εργασίες άρσης επικινδυνότητας και μικροεπισκευές αποκατάστασης ευρημάτων ελέγχου (αντικαταστάσεις εξαρτημάτων, αποκατάσταση γειώσεων, σημάνσεις), συμπεριλαμβανομένων των μικροϋλικών. Τιμή ανά ώρα εργασίας αδειούχου ηλεκτρολόγου.', 'Υ.Α. 101195/17.09.2021 (Β΄ 4654), όπως τροποποιήθηκε και ισχύει · ΕΛΟΤ 60364 ή, κατά περίπτωση, ΕΛΟΤ HD 384/ΚΕΗΕ · σειρά ΕΛΟΤ EN 61557', false, null, 35, true, 5),
  ('SRV02', 'SRV02-06', 'ΥΔΕ κατόπιν τροποποίησης εγκατάστασης', 'ΥΔΕ κατόπιν τροποποίησης εγκατάστασης', 'ΥΔΕ & πιστοποιήσεις', 'τεμ.', '71314100-3', 'Έλεγχος του τροποποιημένου τμήματος εγκατάστασης και έκδοση ΥΔΕ κατόπιν τροποποίησης, με επικαιροποίηση σχεδίων και πρωτοκόλλων.', 'Υ.Α. 101195/17.09.2021 (Β΄ 4654), όπως τροποποιήθηκε και ισχύει · ΕΛΟΤ 60364 ή, κατά περίπτωση, ΕΛΟΤ HD 384/ΚΕΗΕ · σειρά ΕΛΟΤ EN 61557', false, null, 100, true, 6),
  ('SRV02', 'SRV02-07', 'Έκδοση πιστοποιητικού για νέα παροχή ΔΕΔΔΗΕ', 'Έκδοση πιστοποιητικού για νέα παροχή ΔΕΔΔΗΕ', 'ΥΔΕ & πιστοποιήσεις', 'τεμ.', '71314100-3', 'Σύνταξη πλήρους φακέλου για νέα παροχή ΔΕΔΔΗΕ (ΥΔΕ, σχέδια, έντυπα) και ηλεκτρονική υποβολή με παρακολούθηση έως την ολοκλήρωση της ηλεκτροδότησης.', 'Υ.Α. 101195/17.09.2021 (Β΄ 4654), όπως τροποποιήθηκε και ισχύει · ΕΛΟΤ 60364 ή, κατά περίπτωση, ΕΛΟΤ HD 384/ΚΕΗΕ · σειρά ΕΛΟΤ EN 61557', false, null, 120, true, 7),
  ('SRV02', 'SRV02-08', 'Σχεδίαση μονογραμμικού διαγράμματος πίνακα', 'Σχεδίαση μονογραμμικού διαγράμματος πίνακα', 'Σχέδια, μετρήσεις & έλεγχοι', 'τεμ.', '71314100-3', 'Επιτόπια αποτύπωση της εγκατάστασης και σχεδίαση μονογραμμικού διαγράμματος πίνακα σύμφωνα με τα ισχύοντα πρότυπα. Παράδοση σε έντυπη και ηλεκτρονική μορφή.', 'Υ.Α. 101195/17.09.2021 (Β΄ 4654), όπως τροποποιήθηκε και ισχύει · ΕΛΟΤ 60364 ή, κατά περίπτωση, ΕΛΟΤ HD 384/ΚΕΗΕ · σειρά ΕΛΟΤ EN 61557 · IEC 61082-1', false, null, 60, true, 8),
  ('SRV02', 'SRV02-09', 'Έλεγχος & πιστοποίηση πίνακα διανομής', 'Έλεγχος & πιστοποίηση πίνακα διανομής', 'Σχέδια, μετρήσεις & έλεγχοι', 'τεμ.', '71314100-3', 'Οπτικός και λειτουργικός έλεγχος πίνακα διανομής: σύσφιξη συνδέσεων, έλεγχος οργάνων προστασίας, σήμανση κυκλωμάτων, θερμικός έλεγχος. Σύνταξη αναφοράς ευρημάτων.', 'Υ.Α. 101195/17.09.2021 (Β΄ 4654), όπως τροποποιήθηκε και ισχύει · ΕΛΟΤ 60364 ή, κατά περίπτωση, ΕΛΟΤ HD 384/ΚΕΗΕ · σειρά ΕΛΟΤ EN 61557 · ΕΛΟΤ EN IEC 61439', false, null, 80, true, 9),
  ('SRV02', 'SRV02-10', 'Μέτρηση αντίστασης γείωσης', 'Μέτρηση αντίστασης γείωσης', 'Σχέδια, μετρήσεις & έλεγχοι', 'τεμ.', '71314100-3', 'Μέτρηση αντίστασης γείωσης με γειωσόμετρο (τριπολική μέθοδος ή αμπεροτσιμπίδα), καταγραφή τιμών και σύνταξη πρωτοκόλλου μέτρησης.', 'Υ.Α. 101195/17.09.2021 (Β΄ 4654), όπως τροποποιήθηκε και ισχύει · ΕΛΟΤ 60364 ή, κατά περίπτωση, ΕΛΟΤ HD 384/ΚΕΗΕ · σειρά ΕΛΟΤ EN 61557 · ΕΛΟΤ EN 61557-5', false, null, 40, true, 10),
  ('SRV02', 'SRV02-11', 'Έλεγχος διαφορικού διακόπτη (ρελέ διαρροής)', 'Έλεγχος διαφορικού διακόπτη (ρελέ διαρροής)', 'Σχέδια, μετρήσεις & έλεγχοι', 'τεμ.', '71314100-3', 'Δοκιμή διατάξεων διαφορικού ρεύματος (ρελέ διαρροής) με κατάλληλο όργανο: μέτρηση ρεύματος και χρόνου απόζευξης, καταγραφή αποτελεσμάτων.', 'Υ.Α. 101195/17.09.2021 (Β΄ 4654), όπως τροποποιήθηκε και ισχύει · ΕΛΟΤ 60364 ή, κατά περίπτωση, ΕΛΟΤ HD 384/ΚΕΗΕ · σειρά ΕΛΟΤ EN 61557 · ΕΛΟΤ EN 61557-6', false, null, 15, true, 11),
  ('SRV02', 'SRV02-12', 'Κατασκευή/βελτίωση θεμελιακής ή τριγωνικής γείωσης', 'Κατασκευή/βελτίωση θεμελιακής ή τριγωνικής γείωσης', 'Αποκαταστάσεις & ηλεκτρολογικές εργασίες', 'τεμ.', '71314100-3', 'Κατασκευή ή βελτίωση γείωσης (θεμελιακής ή τριγωνικής): προσθήκη ηλεκτροδίων ή ταινίας, συνδέσεις, μετρήσεις πριν και μετά, ώστε να επιτυγχάνονται οι απαιτούμενες από το πρότυπο τιμές.', 'Υ.Α. 101195/17.09.2021 (Β΄ 4654), όπως τροποποιήθηκε και ισχύει · ΕΛΟΤ 60364 ή, κατά περίπτωση, ΕΛΟΤ HD 384/ΚΕΗΕ · σειρά ΕΛΟΤ EN 61557', false, null, 150, true, 12),
