  ('SRV06', 'SRV06-14', 'Συντήρηση πυροσβεστήρα CO2 2kg', 'Συντήρηση πυροσβεστήρα CO2 2kg', 'Πυροσβεστήρες CO₂', 'τεμ.', '50413200-5', 'Ετήσια συντήρηση φορητού πυροσβεστήρα CO2 2 kg κατά την ΚΥΑ 618/43/2005 και το ΕΛΟΤ ΕΝ 3: ζύγιση, έλεγχος βαλβίδας και εξαρτημάτων, σήμανση.', 'Κ.Υ.Α. 618/43/2005, όπως τροποποιήθηκε με Κ.Υ.Α. 17230/671/2005 και Κ.Υ.Α. 140424/2021 · ΕΛΟΤ EN 3, EN 1866 και EN 671, κατά περίπτωση', false, null, 2, true, 14),
  ('SRV06', 'SRV06-15', 'Αναγόμωση πυροσβεστήρα CO2 2kg', 'Αναγόμωση πυροσβεστήρα CO2 2kg', 'Πυροσβεστήρες CO₂', 'τεμ.', '50413200-5', 'Αναγόμωση φορητού πυροσβεστήρα CO2 2 kg με πλήρωση στην ονομαστική ποσότητα και έλεγχο εξαρτημάτων κατά την ΚΥΑ 618/43/2005.', 'Κ.Υ.Α. 618/43/2005, όπως τροποποιήθηκε με Κ.Υ.Α. 17230/671/2005 και Κ.Υ.Α. 140424/2021 · ΕΛΟΤ EN 3, EN 1866 και EN 671, κατά περίπτωση', false, null, 2.2, true, 15),
  ('SRV06', 'SRV06-16', 'Συντήρηση τροχήλατου πυροσβεστήρα CO2 25-30kg', 'Συντήρηση τροχήλατου πυροσβεστήρα CO2 25-30kg', 'Πυροσβεστήρες CO₂', 'τεμ.', '50413200-5', 'Ετήσια συντήρηση τροχήλατου πυροσβεστήρα CO2 25-30 kg κατά την ΚΥΑ 618/43/2005 και το ΕΛΟΤ ΕΝ 1866, με ζύγιση φιάλης, έλεγχο σωλήνα/κώνου και σήμανση.', 'Κ.Υ.Α. 618/43/2005, όπως τροποποιήθηκε με Κ.Υ.Α. 17230/671/2005 και Κ.Υ.Α. 140424/2021 · ΕΛΟΤ EN 3, EN 1866 και EN 671, κατά περίπτωση · ΕΛΟΤ EN 1866', false, null, 9, true, 16),
  ('SRV06', 'SRV06-17', 'Νέος πυροσβεστήρας ξηράς κόνεως 12kg (ABC)', 'Νέος πυροσβεστήρας ξηράς κόνεως 12kg (ABC)', 'Νέοι πυροσβεστήρες', 'τεμ.', '50413200-5', 'Προμήθεια νέου φορητού πυροσβεστήρα ξηράς κόνεως 12 kg (ABC) πιστοποιημένου κατά ΕΛΟΤ ΕΝ 3 με σήμανση CE, πλήρους με στήριγμα.', 'Κ.Υ.Α. 618/43/2005, όπως τροποποιήθηκε με Κ.Υ.Α. 17230/671/2005 και Κ.Υ.Α. 140424/2021 · ΕΛΟΤ EN 3, EN 1866 και EN 671, κατά περίπτωση', false, null, 22, true, 17),
  ('SRV06', 'SRV06-18', 'Νέος πυροσβεστήρας CO2 5kg', 'Νέος πυροσβεστήρας CO2 5kg', 'Νέοι πυροσβεστήρες', 'τεμ.', '50413200-5', 'Προμήθεια νέου φορητού πυροσβεστήρα CO2 5 kg πιστοποιημένου κατά ΕΛΟΤ ΕΝ 3 με σήμανση CE, πλήρους με στήριγμα.', 'Κ.Υ.Α. 618/43/2005, όπως τροποποιήθηκε με Κ.Υ.Α. 17230/671/2005 και Κ.Υ.Α. 140424/2021 · ΕΛΟΤ EN 3, EN 1866 και EN 671, κατά περίπτωση', false, null, 45, true, 18),
  ('SRV06', 'SRV06-19', 'Νέος αυτόματος πυροσβεστήρας οροφής ξηράς κόνεως 6kg', 'Νέος αυτόματος πυροσβεστήρας οροφής ξηράς κόνεως 6kg', 'Νέοι πυροσβεστήρες', 'τεμ.', '50413200-5', 'Προμήθεια νέου αυτόματου πυροσβεστήρα οροφής ξηράς κόνεως 6 kg με θερμοευαίσθητο μηχανισμό ενεργοποίησης και μανόμετρο, κατάλληλου για τοποθέτηση σε λεβητοστάσια/χώρους Η/Μ.', 'Κ.Υ.Α. 618/43/2005, όπως τροποποιήθηκε με Κ.Υ.Α. 17230/671/2005 και Κ.Υ.Α. 140424/2021 · ΕΛΟΤ EN 3, EN 1866 και EN 671, κατά περίπτωση', false, null, 20, true, 19),
  ('SRV06', 'SRV06-20', 'Αντικατάσταση μανομέτρου πυροσβεστήρα', 'Αντικατάσταση μανομέτρου πυροσβεστήρα', 'Ανταλλακτικά πυροσβεστήρων', 'τεμ.', '50413200-5', 'Αντικατάσταση μανομέτρου πυροσβεστήρα με κατάλληλο πιστοποιημένο εξάρτημα και επανέλεγχος στεγανότητας/πίεσης.', 'Κ.Υ.Α. 618/43/2005, όπως τροποποιήθηκε με Κ.Υ.Α. 17230/671/2005 και Κ.Υ.Α. 140424/2021 · ΕΛΟΤ EN 3, EN 1866 και EN 671, κατά περίπτωση', false, null, 4, true, 20),
  ('SRV06', 'SRV06-21', 'Έλεγχος & αναγόμωση πυροσβεστικής φωλιάς/ερμαρίου', 'Έλεγχος & αναγόμωση πυροσβεστικής φωλιάς/ερμαρίου', 'Μόνιμα πυροσβεστικά μέσα', 'τεμ.', '50413200-5', 'Έλεγχος, συντήρηση και αναγόμωση (όπου απαιτείται) πυροσβεστικής φωλιάς/ερμαρίου με μόνιμο υδροδοτικό δίκτυο κατά το πρότυπο ΕΛΟΤ ΕΝ 671, με έλεγχο σωλήνα, ακροφυσίου, βαλβίδας και πίεσης.', 'Κ.Υ.Α. 618/43/2005, όπως τροποποιήθηκε με Κ.Υ.Α. 17230/671/2005 και Κ.Υ.Α. 140424/2021 · ΕΛΟΤ EN 3, EN 1866 και EN 671, κατά περίπτωση · ΕΛΟΤ EN 671', false, null, 15, true, 21),
  ('SRV06', 'SRV06-22', 'Έλεγχος πυροσβεστικού κρουνού/συγκροτήματος', 'Έλεγχος πυροσβεστικού κρουνού/συγκροτήματος', 'Μόνιμα πυροσβεστικά μέσα', 'τεμ.', '50413200-5', 'Έλεγχος καλής λειτουργίας πυροσβεστικού κρουνού/συγκροτήματος (πίεση, παροχή, στεγανότητα, εξαρτήματα) με σύνταξη σχετικής βεβαίωσης.', 'Κ.Υ.Α. 618/43/2005, όπως τροποποιήθηκε με Κ.Υ.Α. 17230/671/2005 και Κ.Υ.Α. 140424/2021 · ΕΛΟΤ EN 3, EN 1866 και EN 671, κατά περίπτωση', false, null, 30, true, 22),
  ('SRV07', 'SRV07-01', 'Μηνιαίο πρόγραμμα συντήρησης ανελκυστήρα έως 6 στάσεις (2 επισκέψεις/μήνα σε δημοτικό κτίριο προσβάσιμο στο κοινό)', 'Μηνιαίο πρόγραμμα συντήρησης ανελκυστήρα έως 6 στάσεις (2 επισκέψεις/μήνα σε δημοτικό κτίριο προσβάσιμο στο κοινό)', 'Τακτική συντήρηση', 'μήνας', '50750000-7', 'Πρόγραμμα τακτικής προληπτικής συντήρησης ηλεκτροκίνητου ανελκυστήρα έως 6 στάσεων σύμφωνα με την ΚΥΑ Φ.Α/9.2/ΟΙΚ.28425/2008 και τη σειρά προτύπων ΕΛΟΤ ΕΝ 81: έλεγχος και ρύθμιση μηχανισμών κίνησης, θυρών, διατάξεων ασφαλείας και πέδησης, λίπανση, καθαρισμός μηχανοστασίου/φρέατος. Από αδειοδοτημένο συνεργείο συντήρησης εγγεγραμμένο σε μητρώο. Παραδοτέο: ενυπόγραφο δελτίο συντήρησης στο βιβλιάριο. Για ανελκυστήρα σε δημοτικό κτίριο ή άλλο χώρο προσβάσιμο στο ευρύ κοινό εκτελούνται δύο (2) επισκέψεις ανά μήνα. Πριν από την πρώτη τακτική συντήρηση επιβεβαιώνεται και αναγράφεται στο δελτίο ο αριθμός απογραφής του Εθνικού Μητρώου.', 'Κ.Υ.Α. Φ.Α/9.2/οικ.28425/1245/2008, όπως ισχύει · Κ.Υ.Α. 59210/2025 · άρθρο 137 Ν. 5317/2026 · ΕΛΟΤ EN 81-20/50, EN 81-28 και EN 81-40/41, κατά περίπτωση · οδηγίες κατασκευαστή', false, null, 45, true, 1),
  ('SRV07', 'SRV07-02', 'Μηνιαίο πρόγραμμα συντήρησης ανελκυστήρα 7–12 στάσεις (2 επισκέψεις/μήνα σε δημοτικό κτίριο προσβάσιμο στο κοινό)', 'Μηνιαίο πρόγραμμα συντήρησης ανελκυστήρα 7–12 στάσεις (2 επισκέψεις/μήνα σε δημοτικό κτίριο προσβάσιμο στο κοινό)', 'Τακτική συντήρηση', 'μήνας', '50750000-7', 'Πρόγραμμα τακτικής προληπτικής συντήρησης ανελκυστήρα 7-12 στάσεων κατά την ΚΥΑ Φ.Α/9.2/ΟΙΚ.28425/2008 και το ΕΛΟΤ ΕΝ 81, με τον απαιτούμενο για τον αριθμό στάσεων αριθμό επισκέψεων/εργασιών ελέγχου και δελτίο συντήρησης. Για ανελκυστήρα σε δημοτικό κτίριο ή άλλο χώρο προσβάσιμο στο ευρύ κοινό εκτελούνται δύο (2) επισκέψεις ανά μήνα. Πριν από την πρώτη τακτική συντήρηση επιβεβαιώνεται και αναγράφεται στο δελτίο ο αριθμός απογραφής του Εθνικού Μητρώου.', 'Κ.Υ.Α. Φ.Α/9.2/οικ.28425/1245/2008, όπως ισχύει · Κ.Υ.Α. 59210/2025 · άρθρο 137 Ν. 5317/2026 · ΕΛΟΤ EN 81-20/50, EN 81-28 και EN 81-40/41, κατά περίπτωση · οδηγίες κατασκευαστή', false, null, 65, true, 2),
  ('SRV07', 'SRV07-03', 'Περιοδικός έλεγχος & πιστοποίηση ανελκυστήρα από αναγνωρισμένο φορέα, όταν απαιτείται', 'Περιοδικός έλεγχος & πιστοποίηση ανελκυστήρα από αναγνωρισμένο φορέα, όταν απαιτείται', 'Έλεγχοι, πιστοποίηση & μητρώο', 'τεμ.', '50750000-7', 'Ετήσιος περιοδικός έλεγχος και επανέλεγχος από αναγνωρισμένο/κοινοποιημένο φορέα ελέγχου, σύμφωνα με την ΚΥΑ Φ.Α/9.2/ΟΙΚ.28425/2008, με έκδοση πιστοποιητικού ελέγχου και ενέργειες για την καταχώριση/ανανέωση στο μητρώο του Δήμου.', 'Κ.Υ.Α. Φ.Α/9.2/οικ.28425/1245/2008, όπως ισχύει · Κ.Υ.Α. 59210/2025 · άρθρο 137 Ν. 5317/2026 · ΕΛΟΤ EN 81-20/50, EN 81-28 και EN 81-40/41, κατά περίπτωση · οδηγίες κατασκευαστή', false, null, 180, true, 3),
  ('SRV07', 'SRV07-04', 'Συντήρηση αναβατορίου/πλατφόρμας ΑμεΑ (μηνιαία)', 'Συντήρηση αναβατορίου/πλατφόρμας ΑμεΑ (μηνιαία)', 'Τακτική συντήρηση', 'μήνας', '50750000-7', 'Μηνιαία συντήρηση αναβατορίου ή πλατφόρμας ΑμεΑ σύμφωνα με τα ισχύοντα πρότυπα (ΕΝ 81-40/81-41) και τις οδηγίες του κατασκευαστή, με έλεγχο διατάξεων ασφαλείας και δελτίο συντήρησης.', 'Κ.Υ.Α. Φ.Α/9.2/οικ.28425/1245/2008, όπως ισχύει · Κ.Υ.Α. 59210/2025 · άρθρο 137 Ν. 5317/2026 · ΕΛΟΤ EN 81-20/50, EN 81-28 και EN 81-40/41, κατά περίπτωση · οδηγίες κατασκευαστή · ΕΛΟΤ EN 81-40/41', false, null, 40, true, 4),
  ('SRV07', 'SRV07-05', 'Αποκατάσταση βλάβης (εργατοώρα τεχνικού)', 'Αποκατάσταση βλάβης (εργατοώρα τεχνικού)', 'Επισκευές & αναβαθμίσεις', 'ώρα', '50750000-7', 'Έκτακτη επέμβαση αποκατάστασης βλάβης: προσέλευση εντός του συμβατικού χρόνου από την κλήση, διάγνωση και αποκατάσταση. Τιμή ανά ώρα τεχνικού (τα ανταλλακτικά τιμολογούνται χωριστά κατόπιν έγκρισης).', 'Κ.Υ.Α. Φ.Α/9.2/οικ.28425/1245/2008, όπως ισχύει · Κ.Υ.Α. 59210/2025 · άρθρο 137 Ν. 5317/2026 · ΕΛΟΤ EN 81-20/50, EN 81-28 και EN 81-40/41, κατά περίπτωση · οδηγίες κατασκευαστή', false, null, 40, true, 5),
  ('SRV07', 'SRV07-06', 'Μηνιαίο πρόγραμμα συντήρησης υδραυλικού ανελκυστήρα (2 επισκέψεις/μήνα σε δημοτικό κτίριο προσβάσιμο στο κοινό)', 'Μηνιαίο πρόγραμμα συντήρησης υδραυλικού ανελκυστήρα (2 επισκέψεις/μήνα σε δημοτικό κτίριο προσβάσιμο στο κοινό)', 'Τακτική συντήρηση', 'μήνας', '50750000-7', 'Πρόγραμμα τακτικής προληπτικής συντήρησης υδραυλικού ανελκυστήρα κατά την ΚΥΑ Φ.Α/9.2/ΟΙΚ.28425/2008 και το ΕΛΟΤ ΕΝ 81-20/50, με έλεγχο αντλητικού συγκροτήματος, στάθμης και διαρροών λαδιού, βαλβίδων και εμβόλου, και δελτίο συντήρησης. Για ανελκυστήρα σε δημοτικό κτίριο ή άλλο χώρο προσβάσιμο στο ευρύ κοινό εκτελούνται δύο (2) επισκέψεις ανά μήνα. Πριν από την πρώτη τακτική συντήρηση επιβεβαιώνεται και αναγράφεται στο δελτίο ο αριθμός απογραφής του Εθνικού Μητρώου.', 'Κ.Υ.Α. Φ.Α/9.2/οικ.28425/1245/2008, όπως ισχύει · Κ.Υ.Α. 59210/2025 · άρθρο 137 Ν. 5317/2026 · ΕΛΟΤ EN 81-20/50, EN 81-28 και EN 81-40/41, κατά περίπτωση · οδηγίες κατασκευαστή', false, null, 50, true, 6),
  ('SRV07', 'SRV07-07', 'Ετήσιο πρόγραμμα συντήρησης ανελκυστήρα έως 6 στάσεων (24 επισκέψεις για δημοτικό κτίριο προσβάσιμο στο κοινό)', 'Ετήσιο πρόγραμμα συντήρησης ανελκυστήρα έως 6 στάσεων (24 επισκέψεις για δημοτικό κτίριο προσβάσιμο στο κοινό)', 'Τακτική συντήρηση', 'τεμ.', '50750000-7', 'Ετήσιο πρόγραμμα τακτικής συντήρησης με είκοσι τέσσερις (24) επισκέψεις, δύο ανά μήνα, για ανελκυστήρα δημοτικού κτιρίου προσβάσιμου στο κοινό, σύμφωνα με το άρθρο 4 της Κ.Υ.Α. Φ.Α/9.2/οικ.28425/1245/2008. Περιλαμβάνονται οι προβλεπόμενοι έλεγχοι, καθαρισμοί, λιπάνσεις, ρυθμίσεις, ενημέρωση βιβλιαρίου και ενυπόγραφο δελτίο κάθε επίσκεψης.', 'Κ.Υ.Α. Φ.Α/9.2/οικ.28425/1245/2008, όπως ισχύει · Κ.Υ.Α. 59210/2025 · άρθρο 137 Ν. 5317/2026 · ΕΛΟΤ EN 81-20/50, EN 81-28 και EN 81-40/41, κατά περίπτωση · οδηγίες κατασκευαστή', false, null, 480, true, 7),
  ('SRV07', 'SRV07-08', 'Αντικατάσταση συρματόσχοινων ανάρτησης', 'Αντικατάσταση συρματόσχοινων ανάρτησης', 'Επισκευές & αναβαθμίσεις', 'τεμ.', '50750000-7', 'Αντικατάσταση συρματόσχοινων ανάρτησης με νέα, πιστοποιημένα κατά τις προδιαγραφές του κατασκευαστή, με ρύθμιση ομοιόμορφης τάνυσης και ελέγχους ασφαλείας.', 'Κ.Υ.Α. Φ.Α/9.2/οικ.28425/1245/2008, όπως ισχύει · Κ.Υ.Α. 59210/2025 · άρθρο 137 Ν. 5317/2026 · ΕΛΟΤ EN 81-20/50, EN 81-28 και EN 81-40/41, κατά περίπτωση · οδηγίες κατασκευαστή', false, null, 450, true, 8),
  ('SRV07', 'SRV07-09', 'Αντικατάσταση πλακέτας ελέγχου (κάρτας)', 'Αντικατάσταση πλακέτας ελέγχου (κάρτας)', 'Επισκευές & αναβαθμίσεις', 'τεμ.', '50750000-7', 'Αντικατάσταση ηλεκτρονικής πλακέτας ελέγχου (κάρτας) με γνήσια ή συμβατή, παραμετροποίηση και δοκιμές λειτουργίας και ασφαλείας.', 'Κ.Υ.Α. Φ.Α/9.2/οικ.28425/1245/2008, όπως ισχύει · Κ.Υ.Α. 59210/2025 · άρθρο 137 Ν. 5317/2026 · ΕΛΟΤ EN 81-20/50, EN 81-28 και EN 81-40/41, κατά περίπτωση · οδηγίες κατασκευαστή', false, null, 350, true, 9),
  ('SRV07', 'SRV07-10', 'Αντικατάσταση μπουτονιέρας/κουμπιών ορόφου', 'Αντικατάσταση μπουτονιέρας/κουμπιών ορόφου', 'Επισκευές & αναβαθμίσεις', 'τεμ.', '50750000-7', 'Αντικατάσταση μπουτονιέρας ή κομβίων ορόφου/θαλάμου με ανταλλακτικά συμβατά με το σύστημα, με έλεγχο ενδείξεων και λειτουργίας.', 'Κ.Υ.Α. Φ.Α/9.2/οικ.28425/1245/2008, όπως ισχύει · Κ.Υ.Α. 59210/2025 · άρθρο 137 Ν. 5317/2026 · ΕΛΟΤ EN 81-20/50, EN 81-28 και EN 81-40/41, κατά περίπτωση · οδηγίες κατασκευαστή', false, null, 40, true, 10),
  ('SRV07', 'SRV07-11', 'Αντικατάσταση φωτοκουρτίνας θυρών', 'Αντικατάσταση φωτοκουρτίνας θυρών', 'Επισκευές & αναβαθμίσεις', 'τεμ.', '50750000-7', 'Αντικατάσταση φωτοκουρτίνας (φωτοηλεκτρικής προστασίας θυρών) κατά ΕΝ 81-20, με έλεγχο ασφαλούς αναστροφής/ακινητοποίησης.', 'Κ.Υ.Α. Φ.Α/9.2/οικ.28425/1245/2008, όπως ισχύει · Κ.Υ.Α. 59210/2025 · άρθρο 137 Ν. 5317/2026 · ΕΛΟΤ EN 81-20/50, EN 81-28 και EN 81-40/41, κατά περίπτωση · οδηγίες κατασκευαστή · ΕΛΟΤ EN 81-20', false, null, 180, true, 11),
